from collections import deque
R,C=len(grid),len(grid[0]); paint=set()
def comp(r,c):
    q=[(r,c)]; seen={(r,c)}
    while q:
        y,x=q.pop()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(y+dy,x+dx)
            if 0<=p[0]<R and 0<=p[1]<C and grid[p[0]][p[1]]==2 and p not in seen:
                seen.add(p);q.append(p)
    return seen
# rays top/bottom col5; left/right rows4,11
for coords in [[(r,5) for r in range(R)],[(r,5) for r in range(R-1,-1,-1)],[(4,c) for c in range(C)],[(4,c) for c in range(C-1,-1,-1)],[(11,c) for c in range(C)],[(11,c) for c in range(C-1,-1,-1)]]:
    for r,c in coords:
        if grid[r][c]==2:
            paint |= comp(r,c);break
out=[row[:] for row in grid]
for r,c in paint: out[r][c]=1
for r in range(R): out[r][5]=1
for c in range(C): out[4][c]=1;out[11][c]=1
print(len(out), sorted(set(map(len,out))))
for row in out: print(' '.join(map(str,row)))
